    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --surface: #ffffff;
        --surface-alt: #eef3f8;
        --text: #172033;
        --muted: #5f6b83;
        --border: #cdd7e6;
        --border-strong: #8090a8;
        --primary: #2457ff;
        --primary-dark: #1d46cc;
        --focus: #0f4cff;
        --shadow: 0 18px 40px rgba(23, 32, 51, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, #ffffff 0, #f4f7fb 40%, #edf2f8 100%);
        min-height: 100vh;
      }

