        display: grid;
        gap: 1.5rem;
        grid-template-columns: minmax(0, 1.2fr) minmax(20rem, 0.8fr);
        align-items: start;
      }

      .hero,
      .card {
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: 1.5rem;
        box-shadow: var(--shadow);
      }

      .hero {
        padding: 2rem;
      }

      h1 {
        margin: 0 0 0.75rem;
        font-size: clamp(2rem, 3vw, 3rem);
        line-height: 1.1;
        letter-spacing: -0.03em;
      }

      .lede {
        margin: 0;
        max-width: 38rem;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.6;
      }

      .card {
        padding: 1.5rem;
      }

      .form-field {
        margin: 0;
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
        min-width: 0;
      }

      legend {
        padding: 0;
        margin-bottom: 0.75rem;
        font-size: 1.1rem;
        font-weight: 700;
      }

      .helper {
        margin: 0 0 1rem;
        color: var(--muted);
        line-height: 1.5;
      }

      .choices {
        display: grid;
        gap: 0.75rem;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .choice {
        display: flex;
        align-items: center;
        gap: 0.9rem;
        padding: 0.95rem 1rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: var(--surface-alt);
        transition: border-color 0.18s ease, background-color 0.18s ease, transform 0.18s ease;
      }

      .choice:hover {
        border-color: var(--border-strong);
        transform: translateY(-1px);
      }

      .choice input {
        width: 1.125rem;
        height: 1.125rem;
        margin: 0;
        accent-color: var(--primary);
        flex: 0 0 auto;
      }

      .choice span {
        font-weight: 600;
      }

      .choice:has(input:focus-visible) {
        outline: 3px solid var(--focus);
        outline-offset: 2px;
      }

      .actions {
        margin-top: 1.25rem;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.35rem;
        font: inherit;
        font-weight: 700;
        color: #fff;
        background: linear-gradient(135deg, var(--primary), var(--primary-dark));
        box-shadow: 0 12px 24px rgba(36, 87, 255, 0.24);
        cursor: pointer;
        min-width: 10rem;
      }

      button:hover {
        filter: brightness(1.03);
      }

      button:focus-visible,
      input:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .status {
        margin: 1rem 0 0;
        min-height: 1.5rem;
        color: var(--muted);
      }

      @media (max-width: 48rem) {
        main {
          padding-top: 4rem;
        }

        .page-shell {
          grid-template-columns: 1fr;
        }

        .hero,
        .card {
          padding: 1.25rem;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-alt: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --border: ButtonBorder;
          --border-strong: ButtonBorder;
          --primary: ButtonText;
          --primary-dark: ButtonText;
          --focus: Highlight;
        }

        .hero,
        .card,
        .choice,
        .skip-link {
          forced-color-adjust: auto;
        }

        button {
          background: ButtonFace;
          color: ButtonText;
          border: 1px solid ButtonBorder;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content">
      <div id="app"></div>
    </main>

    <script>
      const App = () => `
        <section class="page-shell" aria-labelledby="page-title">
          <div class="hero">
            <h1 id="page-title">Notification settings</h1>
            <p class="lede">
              Choose the channel you prefer so we can send important updates in the right place.
            </p>
          </div>

          <div class="card">
            <form id="notification-form" novalidate>
              <div class="form-field">
                <fieldset>
                  <legend>How do you prefer to receive notifications?</legend>
                  <p class="helper">Select one option before submitting.</p>
                  <ul class="choices" role="list">
                    ${RadioOption("email", "Email", true)}
                    ${RadioOption("sms", "SMS")}
                    ${RadioOption("push", "Push Notifications")}
                  </ul>
                </fieldset>
              </div>

              <div class="actions">
                <button type="submit">Submit</button>
              </div>

              <p id="status" class="status" aria-live="polite"></p>
            </form>
          </div>
        </section>
      `;

      const RadioOption = (value, label, required = false) => `
        <li>
          <label class="choice">
            <input
              type="radio"
              name="notification"
              value="${value}"
              ${required ? 'required' : ''}
            />
            <span>${label}</span>
          </label>
        </li>
      `;

      document.getElementById("app").innerHTML = App();

      const form = document.getElementById("notification-form");
      const status = document.getElementById("status");

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!form.checkValidity()) {
          const firstInvalid = form.querySelector(":invalid");
          if (firstInvalid) firstInvalid.focus();
          form.reportValidity();
          status.textContent = "Please select a notification preference before submitting.";
          return;
        }

        const selected = form.notification.value;
        status.textContent = `Saved: ${selected}.`;
      });
    </script>
  </body>
</html>
