      const App = () => `
        <section class="page-shell" aria-labelledby="page-title">
          <div class="hero">
            <h1 id="page-title">Notification settings</h1>
            <p class="lede">
              Choose the channel you prefer so we can send important updates in the right place.
            </p>
          </div>

          <div class="card">
            <form id="notification-form" novalidate>
              <div class="form-field">
                <fieldset aria-describedby="notification-help notification-status">
                  <legend>How do you prefer to receive notifications?</legend>
                  <p class="helper" id="notification-help">Select one option before submitting.</p>
                  <ul class="choices">
                    ${RadioOption("email", "Email", true)}
                    ${RadioOption("sms", "SMS")}
                    ${RadioOption("push", "Push Notifications")}
                  </ul>
                </fieldset>
              </div>

              <div class="actions">
                <button type="submit">Submit</button>
              </div>

              <p id="notification-status" class="status" aria-live="polite"></p>
            </form>
          </div>
        </section>
      `;

      const RadioOption = (value, label, required = false) => `
        <li>
          <label class="choice">
            <input
              type="radio"
              name="notification"
              value="${value}"
              ${required ? 'required' : ''}
            />
            <span>${label}</span>
          </label>
        </li>
      `;

      document.getElementById("app").innerHTML = App();

      const form = document.getElementById("notification-form");
      const status = document.getElementById("notification-status");
      const labels = {
        email: "Email",
        sms: "SMS",
        push: "Push Notifications",
      };

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!form.checkValidity()) {
          const firstInvalid = form.querySelector(":invalid");
          if (firstInvalid) firstInvalid.focus();
          form.reportValidity();
          status.textContent = "Please select a notification preference before submitting.";
          return;
        }

        const selected = form.notification.value;
        status.textContent = `Saved: ${labels[selected]}.`;
      });
    </script>
